package policy

import (
	_ "embed"
	"fmt"
	"slices"
	"strings"
	"sync"
)

// Words.txt is the English words cohere-go/consistency-require-separated-folder-words splits a run-together folder
// name into: cspell's en_US and software-terms dictionaries, lowercased, with the house's own words from
// HouseWords.txt, generated by policy/tools/generate_words/generate_words.mjs, whose header says how to run it. It is
// data rather than code, so a word the lists lack joins HouseWords.txt with its reason, reviewed like any policy
// change, never as a literal in a rule. The licenses the words come under are in `Words.NOTICE`. Swift compiles in
// nothing of it until a Swift rule reads it.
//
//go:embed Words.txt
var wordsFile []byte

// wordsCommentPrefix opens each of the file's header lines.
const wordsCommentPrefix = "#"

// Words is a sorted list of lowercase words, read from Words.txt.
type Words struct {
	// sorted is every word once, in byte order, each a slice of one string holding the file, not a copy apiece.
	sorted []string
}

// Has reports whether word is in the list, spelled exactly: the list is lowercase, so a capital never matches.
func (words Words) Has(word string) bool {
	_, found := slices.BinarySearch(words.sorted, word)
	return found
}

// Count is how many words the list holds.
func (words Words) Count() int {
	return len(words.sorted)
}

// KnownWords is the embedded Words.txt, read the first time a caller asks and never again. It is read lazily, unlike
// Brands, because it is 150,000 lines that only one rule reads, and a run that never reaches that rule, such as
// `--version` or a TypeScript-only project, should not pay for it. An invalid file panics on that first read, since a
// list read wrongly would split names no word list holds while the rule's tests reported it clean.
var KnownWords = sync.OnceValue(func() Words {
	words, loadError := loadWords(wordsFile)
	if loadError != nil {
		// Invariant: the file is embedded and its loader is tested, so a refusal here is a broken build of policy,
		// and running with a list read wrongly would report folders no word list splits.
		panic(fmt.Sprintf("Words.txt: %v", loadError))
	}
	return words
})

// loadWords reads the file: the comment lines that open it, then one word a line, each lowercase ASCII letters
// alone and after the one before it in byte order, so a duplicate, a misplaced word or a hand edit out of order is
// refused rather than read, and Has can search the list as it stands. A comment after the first word is refused too,
// since the generator writes none there.
func loadWords(data []byte) (Words, error) {
	text, endsWithNewline := strings.CutSuffix(string(data), "\n")
	if !endsWithNewline {
		return Words{}, fmt.Errorf("the file does not end with a newline, so its last word may be cut short")
	}
	lines := strings.Split(text, "\n")
	words := Words{sorted: make([]string, 0, len(lines))}
	for index, line := range lines {
		if len(words.sorted) == 0 && strings.HasPrefix(line, wordsCommentPrefix) {
			continue
		}
		if !isLowercaseLetters(line) {
			return Words{}, fmt.Errorf("line %d, %q, is not lowercase ASCII letters alone", index+1, line)
		}
		if count := len(words.sorted); count > 0 && line <= words.sorted[count-1] {
			return Words{}, fmt.Errorf("line %d, %q, does not come after %q, so the list is not sorted and "+
				"deduplicated", index+1, line, words.sorted[count-1])
		}
		words.sorted = append(words.sorted, line)
	}
	if len(words.sorted) == 0 {
		return Words{}, fmt.Errorf("the file holds no words")
	}
	return words, nil
}

// isLowercaseLetters reports whether text is one or more of the letters a to z and nothing else.
func isLowercaseLetters(text string) bool {
	if text == "" {
		return false
	}
	for index := 0; index < len(text); index++ {
		if text[index] < 'a' || text[index] > 'z' {
			return false
		}
	}
	return true
}
